(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-714":{scenario:{company:"Son Tra Biomedical",supervisor:{name:"Tạ Quỳnh Anh",role:{vi:"Trưởng phòng Medical Affairs",en:"Medical Affairs Manager"}},ref_code:"CR-5093",title:{vi:"Dữ liệu cân bằng. Báo cáo kịp thời. Đạo đức trước.",en:"Balanced data. Timely reporting. Ethics first."},brief:{vi:"Đây là tình huống đào tạo. Sau buổi gặp bác sĩ tim mạch, bạn hoàn thiện báo cáo CR-5093 cho thuốc hạ lipid Vastorel (sản phẩm mô phỏng). Bác sĩ cho biết một người bệnh phải nhập viện vì đau cơ, CK tăng cao sau 2 tuần dùng thuốc. Slide trình bày dùng nghiên cứu 3 năm: biến cố tim mạch chính 12,4% ở nhóm chứng và 9,9% ở nhóm điều trị. Đối chiếu báo cáo nháp với tài liệu đã duyệt, sửa phân loại biến cố bất lợi và số NNT, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. After a cardiologist visit you complete call report CR-5093 for the lipid-lowering drug Vastorel (a simulated product). The doctor said one patient was hospitalized with muscle pain and high CK after 2 weeks on it. The slide deck uses a 3-year study: major cardiovascular events 12.4% in the control arm and 9.9% in the treatment arm. Compare the draft report with the approved materials, correct the adverse event classification and the NNT, then write an evidence-based report."},reference_title:{vi:"SOP cảnh giác dược & tóm tắt nghiên cứu đã duyệt",en:"Pharmacovigilance SOP & approved study summary"},fields:[{id:"AE_CLASS",label:{vi:"Phân loại biến cố bất lợi",en:"Adverse event classification"},initial:"NON-SERIOUS",expected:"SAE",choices:["NOT-AE","NON-SERIOUS","SAE"],reference:"SOP cảnh giác dược - tiêu chí nghiêm trọng",ref_value:{vi:"SAE (nghiêm trọng) nếu tử vong, đe dọa tính mạng, phải nhập viện hoặc kéo dài nằm viện, tàn tật, dị tật bẩm sinh",en:"SAE (serious) if death, life-threatening, hospitalization or prolonged stay, disability or congenital anomaly"},hint:{vi:"Chỉ cần một tiêu chí nghiêm trọng là đủ, không cần chứng minh chắc chắn do thuốc.",en:"One seriousness criterion is enough; causality does not need to be proven."}},{id:"NNT",label:{vi:"Số người cần điều trị (NNT)",en:"Number needed to treat (NNT)"},initial:"5",expected:"40",reference:"Tóm tắt nghiên cứu 3 năm",ref_value:{vi:"Biến cố tim mạch chính: nhóm chứng 12,4%; nhóm điều trị 9,9%; theo dõi 3 năm",en:"Major cardiovascular events: control 12.4%; treatment 9.9%; 3-year follow-up"},hint:{vi:"NNT dựa trên mức giảm nguy cơ tuyệt đối, không phải mức giảm nguy cơ tương đối.",en:"NNT is based on the absolute risk reduction, not the relative risk reduction."}}],sop32:{vi:"ARR = tỷ lệ biến cố nhóm chứng - tỷ lệ biến cố nhóm điều trị; NNT = 1 / ARR (ARR ở dạng thập phân), làm tròn lên số nguyên. Không dùng RRR thay ARR. Biến cố bất lợi phải chuyển Cảnh giác dược trong 24 giờ.",en:"ARR = control event rate - treatment event rate; NNT = 1 / ARR (as a decimal), rounded up. Never use RRR instead of ARR. Adverse events go to Pharmacovigilance within 24 hours."},context:{label:"CRM / CR-5093",metrics:[{label:{vi:"Biến cố nhóm chứng",en:"Control event rate"},value:"12.4%"},{label:{vi:"Biến cố nhóm điều trị",en:"Treatment event rate"},value:"9.9%"},{label:{vi:"Thời gian theo dõi (năm)",en:"Follow-up (years)"},value:"3"},{label:{vi:"Hạn chuyển báo cáo AE",en:"AE forwarding deadline"},value:"24 h"}]},crisis:{vi:"Quản lý vùng nhắn: “Ca nhập viện bác sĩ chỉ kể miệng, ghi là không phải AE cho gọn, cuối quý đang chạy chỉ tiêu. Tuần sau cứ nói 5 người dùng là cứu được 1, kèm phong bì cảm ơn để bác sĩ kê đều tay.”",en:"Your area manager messages you: “The doctor only mentioned that hospital case, log it as not an AE, we are chasing the quarter target. Next week say treating 5 people saves 1, and bring a thank-you envelope so the doctor keeps prescribing.”"},options:{safe:{vi:"Chuyển báo cáo AE nghiêm trọng cho Cảnh giác dược trong 24 giờ, trình bày ARR và NNT đúng tài liệu đã duyệt, từ chối mọi khoản lợi ích cho bác sĩ và báo Medical Affairs, Compliance.",en:"Forward the serious AE to Pharmacovigilance within 24 hours, present ARR and NNT exactly as approved, refuse any benefit to the doctor and inform Medical Affairs and Compliance."},shortcut:{vi:"Ghi không phải AE, giữ thông điệp “5 người cứu 1” và chuẩn bị phong bì như được giao.",en:"Log it as not an AE, keep the “treat 5, save 1” message and prepare the envelope as told."},wait:{vi:"Chưa ghi gì về ca nhập viện, đợi bác sĩ gửi hồ sơ rồi mới tính.",en:"Record nothing about the hospital case and wait for the doctor to send records first."}},questions:{vi:["Vì sao ca này là SAE và vì sao NNT là 40 chứ không phải 5? Dẫn chứng từ SOP và dữ liệu nghiên cứu.","Bạn xử lý yêu cầu đưa phong bì và thông điệp phóng đại thế nào để tuân thủ quy định thông tin thuốc và quy tắc đạo đức?"],en:["Why is this case an SAE and why is the NNT 40 rather than 5? Cite the SOP and the study data.","How do you handle the envelope request and the exaggerated message in line with drug information rules and ethics codes?"]},hints:{vi:["Đọc tiêu chí nghiêm trọng trong SOP cảnh giác dược và tìm tiêu chí khớp với ca được kể.","Tính ARR từ hai tỷ lệ biến cố trước khi áp dụng công thức NNT ở SOP mục 3.2.","Đọc lại SOP mục 4.2: không che giấu biến cố bất lợi, không trao lợi ích để tác động kê đơn."],en:["Read the seriousness criteria in the PV SOP and find the one matching the reported case.","Work out the ARR from both event rates before applying the NNT formula in SOP 3.2.","Re-read SOP 4.2: never hide adverse events or offer benefits to influence prescribing."]}},learning:{summary:{vi:"Trình dược viên và chuyên viên tư vấn khoa học y khoa (MSL) cung cấp thông tin thuốc chính xác, cân bằng cho nhân viên y tế, hỗ trợ sử dụng thuốc hợp lý và ghi nhận phản hồi từ thực hành lâm sàng. Người làm nghề hiểu dược lý, đọc được dữ liệu nghiên cứu lâm sàng, tuân thủ quy định thông tin, quảng cáo thuốc, báo cáo biến cố bất lợi kịp thời và giữ quan hệ chuyên nghiệp, minh bạch.",en:"Medical representatives and medical science liaisons (MSL) give healthcare professionals accurate, balanced product information, support rational use and capture feedback from clinical practice. The role requires pharmacology, the ability to read clinical trial data, compliance with drug information and promotion rules, timely adverse event reporting and transparent, professional relationships."},responsibilities:{vi:["Giới thiệu thuốc theo đúng tờ hướng dẫn sử dụng và tài liệu đã được phê duyệt.","Trình bày dữ liệu lâm sàng cân bằng: hiệu quả, an toàn, chỉ định, chống chỉ định.","Ghi nhận và chuyển biến cố bất lợi, khiếu nại chất lượng cho bộ phận chuyên trách đúng hạn.","Chuyển câu hỏi ngoài chỉ định cho bộ phận Thông tin Y khoa trả lời khách quan.","Lập kế hoạch gặp khách hàng, cập nhật CRM và báo cáo hoạt động minh bạch."],en:["Present products strictly within the approved label and materials.","Show balanced clinical data: efficacy, safety, indications and contraindications.","Capture and forward adverse events and quality complaints to the right team on time.","Pass off-label questions to Medical Information for an objective answer.","Plan customer calls, update the CRM and report activities transparently."]},competencies:[{name:{vi:"Kiến thức dược lý & bệnh học",en:"Pharmacology & disease knowledge"},desc:{vi:"Hiểu cơ chế thuốc, bệnh học và vị trí của sản phẩm trong hướng dẫn điều trị.",en:"Understand drug mechanisms, disease and the product's place in treatment guidelines."}},{name:{vi:"Đọc hiểu y học chứng cứ",en:"Evidence-based medicine"},desc:{vi:"Diễn giải đúng ARR, RRR, NNT, khoảng tin cậy và giới hạn của nghiên cứu.",en:"Interpret ARR, RRR, NNT, confidence intervals and study limitations correctly."}},{name:{vi:"Cảnh giác dược",en:"Pharmacovigilance"},desc:{vi:"Nhận diện biến cố bất lợi trong mọi cuộc trao đổi và chuyển báo cáo đúng hạn.",en:"Spot adverse events in any conversation and forward them on time."}},{name:{vi:"Giao tiếp khoa học",en:"Scientific communication"},desc:{vi:"Trao đổi ngắn gọn, khách quan, trả lời câu hỏi khó bằng dữ liệu và dẫn nguồn.",en:"Communicate concisely and objectively and answer hard questions with cited data."}},{name:{vi:"Tuân thủ & đạo đức",en:"Compliance & ethics"},desc:{vi:"Không quảng cáo ngoài chỉ định, không trao lợi ích để tác động kê đơn.",en:"Never promote off-label or offer benefits to influence prescribing."}}],knowledge:{vi:["Luật Dược số 105/2016/QH13 và Nghị định 54/2017/NĐ-CP về thông tin, quảng cáo thuốc.","Quy định hiện hành về người giới thiệu thuốc và hoạt động thông tin thuốc tại cơ sở y tế.","Bộ quy tắc thực hành IFPMA về tương tác với nhân viên y tế.","ICH E2A: định nghĩa và tiêu chí biến cố bất lợi nghiêm trọng.","Y học chứng cứ: thiết kế nghiên cứu, ARR, RRR, NNT, NNH và khoảng tin cậy.","Khái niệm sử dụng ngoài chỉ định và tờ hướng dẫn sử dụng được phê duyệt."],en:["Pharmacy Law No. 105/2016/QH13 and Decree 54/2017/ND-CP on drug information and advertising.","Current rules on medical representatives and drug information activities in healthcare facilities.","The IFPMA Code of Practice on interactions with healthcare professionals.","ICH E2A definitions and seriousness criteria for adverse events.","Evidence-based medicine: study design, ARR, RRR, NNT, NNH and confidence intervals.","Off-label use and the approved product label."]},tools:["Phần mềm CRM quản lý khách hàng","Bộ trình bày điện tử đã phê duyệt","Cơ sở dữ liệu y văn PubMed","Biểu mẫu báo cáo biến cố bất lợi","Microsoft Excel / Power BI"],kpis:{vi:["Tỷ lệ biến cố bất lợi được chuyển báo cáo trong 24 giờ (mục tiêu 100%).","Số cuộc gặp có trao đổi khoa học chất lượng theo kế hoạch.","Kết quả kiểm tra tuân thủ tài liệu và hoạt động (không vi phạm).","Mức độ hài lòng của nhân viên y tế về chất lượng thông tin."],en:["Share of adverse events forwarded within 24 hours (target 100%).","Planned calls with quality scientific exchange.","Compliance audit results on materials and activities (no breaches).","Healthcare professional satisfaction with information quality."]},day:[{time:"07:30",vi:"Xem kế hoạch tuyến, đọc cập nhật y văn và tài liệu mới được duyệt.",en:"Review the territory plan, recent literature and newly approved materials."},{time:"09:00",vi:"Gặp bác sĩ tại bệnh viện theo lịch hẹn, trình bày dữ liệu đã duyệt.",en:"Meet doctors at the hospital as booked and present approved data."},{time:"11:30",vi:"Ghi nhận phản hồi, chuyển ngay biến cố bất lợi hoặc câu hỏi ngoài chỉ định.",en:"Log feedback and immediately forward adverse events or off-label questions."},{time:"14:00",vi:"Tham dự sinh hoạt khoa học tại bệnh viện theo đúng quy định.",en:"Attend a hospital scientific session in line with the rules."},{time:"17:00",vi:"Cập nhật CRM, báo cáo hoạt động và chuẩn bị kế hoạch ngày mai.",en:"Update the CRM, report activities and plan tomorrow."}],mistakes:{vi:["Dùng mức giảm nguy cơ tương đối để phóng đại hiệu quả thuốc.","Không nhận ra biến cố bất lợi khi bác sĩ chỉ kể miệng nên không báo cáo.","Trao quà, tiền hoặc chuyến đi để đổi lấy cam kết kê đơn."],en:["Using relative risk reduction to exaggerate efficacy.","Missing an adverse event because the doctor only mentioned it verbally.","Offering gifts, cash or trips in exchange for prescribing commitments."]},career:[{vi:"Trình dược viên",en:"Medical representative"},{vi:"Trình dược viên cấp cao / Chuyên viên sản phẩm",en:"Senior medical representative / Product specialist"},{vi:"Chuyên viên tư vấn khoa học y khoa (MSL)",en:"Medical science liaison (MSL)"},{vi:"Trưởng phòng Medical Affairs",en:"Head of Medical Affairs"}],glossary:[{term:"AE",vi:"Biến cố bất lợi: bất kỳ sự cố y khoa không mong muốn nào xảy ra khi dùng thuốc, chưa cần chứng minh do thuốc.",en:"Adverse event: any untoward medical occurrence during drug use, causality not required."},{term:"SAE",vi:"Biến cố bất lợi nghiêm trọng: gây tử vong, đe dọa tính mạng, nhập viện, tàn tật hoặc dị tật bẩm sinh.",en:"Serious adverse event: causing death, life threat, hospitalization, disability or congenital anomaly."},{term:"ARR",vi:"Mức giảm nguy cơ tuyệt đối: hiệu số tỷ lệ biến cố giữa nhóm chứng và nhóm điều trị.",en:"Absolute risk reduction: the difference in event rates between control and treatment."},{term:"NNT",vi:"Số người cần điều trị để ngăn một biến cố, bằng 1 chia ARR.",en:"Number needed to treat to prevent one event, equal to 1 divided by ARR."},{term:"Off-label",vi:"Sử dụng thuốc ngoài chỉ định, liều hoặc đối tượng được phê duyệt trên tờ hướng dẫn sử dụng.",en:"Use outside the indication, dose or population approved in the product label."}],quiz:[{q:{vi:"Tỷ lệ biến cố nhóm chứng 10%, nhóm điều trị 6%. NNT là bao nhiêu?",en:"Control event rate 10%, treatment 6%. What is the NNT?"},options:{vi:["NNT 4","NNT 40","NNT 2,5","NNT 25"],en:["NNT 4","NNT 40","NNT 2.5","NNT 25"]},answer:3,explain:{vi:"Mức giảm nguy cơ tuyệt đối ARR = 10% - 6% = 4% = 0,04; NNT = 1 / 0,04 = 25.",en:"ARR = 10% - 6% = 4% = 0.04; NNT = 1 / 0.04 = 25."}},{q:{vi:"Bác sĩ kể người bệnh nhập viện sau khi dùng thuốc nhưng chưa chắc do thuốc. Phân loại thế nào?",en:"A doctor says a patient was hospitalized after taking the drug but causality is unclear. How is it classified?"},options:{vi:["Không phải AE","AE nghiêm trọng, phải báo cáo","AE không nghiêm trọng","Chờ bác sĩ xác nhận rồi mới tính"],en:["Not an AE","Serious AE, must be reported","Non-serious AE","Wait for the doctor to confirm"]},answer:1,explain:{vi:"Nhập viện là tiêu chí nghiêm trọng; AE không cần chứng minh quan hệ nhân quả mới báo cáo.",en:"Hospitalization is a seriousness criterion; causality is not required to report an AE."}},{q:{vi:"Bác sĩ hỏi về dùng thuốc cho chỉ định chưa được phê duyệt. Bạn làm gì?",en:"A doctor asks about an unapproved indication. What do you do?"},options:{vi:["Ghi nhận câu hỏi và chuyển bộ phận Thông tin Y khoa trả lời","Tự trình bày dữ liệu ngoài chỉ định","Khuyên bác sĩ cứ thử","Từ chối nói chuyện tiếp"],en:["Log the question and pass it to Medical Information","Present off-label data yourself","Tell the doctor to try it","End the conversation"]},answer:0,explain:{vi:"Trình dược viên không quảng bá ngoài chỉ định; câu hỏi tự nguyện được trả lời khách quan qua kênh y khoa.",en:"Reps must not promote off-label; unsolicited questions get an objective answer via the medical channel."}},{q:{vi:"Quản lý yêu cầu đưa phong bì để bác sĩ kê đơn nhiều hơn. Phản hồi đúng là gì?",en:"Your manager asks you to give an envelope so a doctor prescribes more. What is the right response?"},options:{vi:["Đưa một lần vì là lệnh cấp trên","Đưa quà thay vì tiền","Từ chối và báo bộ phận Compliance","Nhờ đồng nghiệp đưa giúp"],en:["Do it once since it is an order","Give a gift instead of cash","Refuse and report to Compliance","Ask a colleague to deliver it"]},answer:2,explain:{vi:"Trao lợi ích để tác động kê đơn vi phạm pháp luật và quy tắc đạo đức ngành; phải từ chối và báo cáo.",en:"Benefits to influence prescribing break the law and industry codes; refuse and report."}}],tools_en:["CRM software for customer management","Approved e-detailing materials","PubMed literature database","Adverse event report form","Microsoft Excel / Power BI"]}}})})(window.KKR);
